import{_ as e,o,c as i,a2 as s}from"./chunks/framework.CqpfiAoK.js";const u=JSON.parse('{"title":"Teoria e Classificação dos Planos","description":"","frontmatter":{},"headers":[],"relativePath":"pt/80-位面理论与分类.md","filePath":"pt/80-位面理论与分类.md","lastUpdated":null}'),d={name:"pt/80-位面理论与分类.md"};function n(r,a,t,l,c,m){return o(),i("div",null,[...a[0]||(a[0]=[s('<h1 id="teoria-e-classificacao-dos-planos" tabindex="-1">Teoria e Classificação dos Planos <a class="header-anchor" href="#teoria-e-classificacao-dos-planos" aria-label="Permalink to &quot;Teoria e Classificação dos Planos&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Item</th><th>Conteúdo</th></tr></thead><tbody><tr><td>Número do Documento</td><td>80</td></tr><tr><td>Módulo</td><td>Interação interplanar e regras temporais</td></tr><tr><td>Palavras-chave Principais</td><td>Teoria planar, classificação planar, barreira de leis, coordenadas planares, Hengyuanzhou</td></tr></tbody></table><h2 id="i-definicao-basica-de-plano" tabindex="-1">I. Definição Básica de Plano <a class="header-anchor" href="#i-definicao-basica-de-plano" aria-label="Permalink to &quot;I. Definição Básica de Plano&quot;">​</a></h2><p>No quadro do Universo de Origem da Âncora de Todas as Almas (Hengyuanzhou), &quot;plano&quot; refere-se a uma região de existência com continuidade espaço-temporal independente, delimitada por um conjunto de leis relativamente estáveis. Um plano não é simplesmente &quot;outro mundo&quot;, mas uma projeção concretizada da rede de leis em diferentes intervalos de parâmetros. Cada plano possui suas próprias constantes físicas únicas, densidade de energia, velocidade de fluxo temporal e atividade de consciência; esses parâmetros formam conjuntamente a &quot;impressão digital de leis&quot; do plano.</p><p>A existência dos planos origina-se da não uniformidade da rede de leis de Hengyuanzhou. Durante o funcionamento das leis de origem do universo, devido às diferenças na distribuição de energia, perturbações de consciência e evolução histórica, formam-se naturalmente inúmeras regiões de leis com parâmetros diferentes. Essas regiões são separadas por &quot;barreiras de leis&quot;, e a intensidade da barreira depende do grau de diferença dos parâmetros de leis entre planos adjacentes — quanto maior a diferença, mais espessa a barreira e maior a dificuldade de travessia.</p><p>O mecanismo de âncora ocupa uma posição central na teoria planar. A âncora é essencialmente um nó estável na rede de leis; ela não apenas mantém a estabilidade das leis do próprio plano, mas também pode servir como referência de ancoragem para conexões interplanares. Todas as interações, como travessia interplanar, comunicação e arqueologia, devem ser posicionadas e calibradas tendo a âncora como origem de coordenadas.</p><h2 id="ii-sistema-de-classificacao-dos-planos" tabindex="-1">II. Sistema de Classificação dos Planos <a class="header-anchor" href="#ii-sistema-de-classificacao-dos-planos" aria-label="Permalink to &quot;II. Sistema de Classificação dos Planos&quot;">​</a></h2><p>Os planos dentro de Hengyuanzhou são divididos nas seguintes cinco categorias de acordo com os parâmetros de leis, nível de energia e grau de desenvolvimento civilizacional:</p><table tabindex="0"><thead><tr><th>Categoria</th><th>Características de Leis</th><th>Densidade de Energia</th><th>Forma Civilizacional Típica</th><th>Dificuldade de Travessia</th></tr></thead><tbody><tr><td>Plano de base material</td><td>Leis físicas dominam, energia é implícita</td><td>Baixa</td><td>Civilização tecnológica, civilização de cultivo inicial</td><td>Baixa</td></tr><tr><td>Plano de manifestação de energia</td><td>Leis de energia semi-explícitas, sistema de cultivo maduro</td><td>Média</td><td>Civilização de cultivo médio-alto, civilização mágica</td><td>Média</td></tr><tr><td>Plano dominado por consciência</td><td>Leis de consciência explícitas, matéria pode ser moldada pela vontade</td><td>Alta</td><td>Civilização de espíritos, civilização de agregação de consciência</td><td>Alta</td></tr><tr><td>Plano de leis quebradas</td><td>Leis instáveis, existem inúmeras fissuras de leis</td><td>Extremamente alta e caótica</td><td>Plano selvagem, plano de ruínas</td><td>Extremamente alta</td></tr><tr><td>Plano próximo à origem</td><td>Próximo às leis de origem do universo, parâmetros aproximam-se do limite</td><td>Aproxima-se da origem</td><td>Civilização suprema, guardiões de planos</td><td>Limite teórico</td></tr></tbody></table><p>Além das cinco categorias acima, existem alguns tipos especiais de planos, incluindo: plano de espelho (existência paralela altamente simétrica aos parâmetros de leis de um determinado plano), plano de intercalação (região de transição localizada entre as barreiras de leis de dois planos principais), plano dormente (plano antigo com atividade de leis extremamente baixa, quase estagnado) e plano recém-nascido (plano jovem com rede de leis recentemente formada, parâmetros ainda não estáveis).</p><h2 id="iii-coordenadas-planares-e-principio-de-posicionamento" tabindex="-1">III. Coordenadas Planares e Princípio de Posicionamento <a class="header-anchor" href="#iii-coordenadas-planares-e-principio-de-posicionamento" aria-label="Permalink to &quot;III. Coordenadas Planares e Princípio de Posicionamento&quot;">​</a></h2><p>A premissa da interação interplanar é o posicionamento planar preciso. Hengyuanzhou estabeleceu um &quot;sistema de coordenadas planares quadridimensionais&quot; tendo a âncora como referência; cada plano é determinado exclusivamente por quatro parâmetros:</p><ol><li><strong>Código de impressão digital de leis</strong>: Identificador único gerado por operação de hash a partir dos parâmetros de leis centrais do plano, com comprimento de 128 bits</li><li><strong>Grau de correlação de âncora</strong>: Intensidade de conexão do plano com a rede de âncoras conhecida, faixa de valores de 0 a 1</li><li><strong>Razão de velocidade temporal</strong>: Razão entre a velocidade de fluxo temporal do plano e o tempo padrão de Hengyuanzhou, faixa comum de 0,1 a 10</li><li><strong>Número de dimensões espaciais</strong>: Número de dimensões espaciais perceptíveis do plano, geralmente de 3 a 11 dimensões</li></ol><p>Os métodos de obtenção de coordenadas planares incluem: detecção automática da rede de âncoras, retrocesso de sinais de comunicação interplanar, resíduos de coordenadas em ruínas arqueológicas e registro manual de viajantes planares. Todas as coordenadas planares confirmadas são registradas no &quot;Banco Geral de Coordenadas Planares de Hengyuanzhou&quot;, mantido de forma unificada pela Agência de Administração Planares subordinada ao Conselho de Âncoras.</p><h2 id="iv-interacao-natural-entre-planos" tabindex="-1">IV. Interação Natural entre Planos <a class="header-anchor" href="#iv-interacao-natural-entre-planos" aria-label="Permalink to &quot;IV. Interação Natural entre Planos&quot;">​</a></h2><p>Mesmo sem ações de travessia ativa, existem fenômenos de interação natural entre os planos. O mais comum é o &quot;vazamento de leis&quot; — devido à fraqueza local das barreiras entre planos adjacentes, uma pequena quantidade de parâmetros de leis penetram mutuamente, causando fenômenos anômalos locais. Por exemplo, os &quot;eventos sobrenaturais&quot; que ocasionalmente ocorrem em planos de base material são frequentemente causados pelo vazamento de leis de planos de manifestação de energia adjacentes.</p><p>Outra interação natural é a &quot;ressonância planar&quot;. Quando os códigos de impressão digital de leis de dois planos apresentam alto grau de similaridade, ocorre entre eles uma ressonância de leis periódica, manifestada como eventos históricos, tendências civilizacionais e até mesmo destinos de personagens semelhantes ocorrendo em ambos os planos em períodos específicos. A ressonância planar é um importante objeto de estudo da arqueologia planar; através da análise dos padrões de ressonância, pode-se inferir o estado civilizacional de planos desconhecidos.</p><h2 id="conclusao" tabindex="-1">Conclusão <a class="header-anchor" href="#conclusao" aria-label="Permalink to &quot;Conclusão&quot;">​</a></h2><p>A teoria planar é a base teórica de todas as práticas de interação interplanar. Compreender com precisão a essência, classificação e princípio de posicionamento dos planos é a premissa para formular regras de travessia, diretrizes éticas e mecanismos de prevenção e controle. A exploração planar de Hengyuanzhou segue sempre o princípio de &quot;cognição primeiro, interação cautelosa&quot;, garantindo, ao expandir as fronteiras da civilização, que não se cause interferência irreversível na evolução autônoma de qualquer plano.</p><h2 id="documentos-relacionados" tabindex="-1">Documentos Relacionados <a class="header-anchor" href="#documentos-relacionados" aria-label="Permalink to &quot;Documentos Relacionados&quot;">​</a></h2><ul><li>81-Regras de Travessia Planares</li><li>88-Diretrizes Éticas Interplanares</li><li>28-Conexão de Âncora Interplanares</li></ul>',21)])])}const g=e(d,[["render",n]]);export{u as __pageData,g as default};
